// =========================
// 🧠 حالة المحادثة لكل شخص (مخزّنة دائمًا) + قايمة الأخبار المنشورة عمومًا (لمنع التكرار)
const staticData = $getWorkflowStaticData('global');
if (!staticData.chatDrafts) staticData.chatDrafts = {};
if (!staticData.publishedItems) staticData.publishedItems = [];

const body = $json;
const isCallback = !!body.callback_query;
const isMessage = !!body.message && !!body.message.text;

if (!isCallback && !isMessage) {
  return [{ json: { mode: "ignore" } }];
}

function cleanText(t) {
  return (t || "")
    .replace(/[\u200B-\u200F\uFEFF]/g, "")
    .trim()
    .replace(/^[.!؟?,\s]+|[.!؟?,\s]+$/g, "");
}

let chatId, mode, text = "", callbackData = "";

if (isCallback) {
  const cq = body.callback_query;
  chatId = String(cq.message.chat.id);
  callbackData = cq.data || "";
  const draft = staticData.chatDrafts[chatId];

  if (!draft || draft.status !== "awaiting_confirmation") {
    mode = "ignore"; // زرار قديم على مسودة اتشالت
  } else if (callbackData === "publish") {
    mode = "publish";
  } else if (callbackData === "cancel") {
    mode = "cancel";
  } else if (callbackData === "edit") {
    mode = "ask_edit";
    draft.status = "awaiting_edit_text";
  } else {
    mode = "ignore";
  }
} else {
  chatId = String(body.message.chat.id);
  text = cleanText(body.message.text);
  const draft = staticData.chatDrafts[chatId];

  if (draft && draft.status === "awaiting_edit_text") {
    mode = "revise";
  } else {
    // أي نص تاني (حتى لو فيه مسودة معلّقة بانتظار الأزرار) بيتعامل كتاسك جديدة فورًا
    mode = "new";
  }
}

return [{
  json: {
    mode,
    chatId,
    text,
    draft: staticData.chatDrafts[chatId] || null
  }
}];

const staticData = $getWorkflowStaticData('global');
if (!staticData.chatDrafts) staticData.chatDrafts = {};
const chatId = $json.chatId;
delete staticData.chatDrafts[chatId];
return { json: { chatId } };

const mode = $json.mode;
const chatId = $json.chatId;
const text = $json.text;
const draft = $json.draft;

let combinedInput;

if (mode === "new") {
  combinedInput =
`مهمة جديدة: خبر لوجستي جه من موظف عن طريق الشات.
النص/الرابط اللي بعته:
${text}`;
} else {
  // revise
  combinedInput =
`فيه مسودة سابقة اتبعتت، والموظف عايز يعدلها.

المسودة السابقة (JSON):
${JSON.stringify(draft.lastDraft || {}, null, 2)}

طلب التعديل من الموظف:
${text}

مهم: المسودة السابقة دي بالفعل معتمدة على معلومات صحيحة، فمسموح لك تعيد الصياغة أو تطوّل/تقصّر أي جزء منها (زي تفصيل أكتر لنفس الفكرة، أو تحسين الأسلوب) من غير ما يُعتبر ده اختراع معلومات جديدة - طالما إنك بتشتغل على نفس الحقائق الموجودة في المسودة السابقة أو المذكورة في طلب التعديل نفسه. الممنوع فقط هو إضافة أرقام أو أحداث أو تفاصيل حقيقية جديدة تمامًا مش موجودة في المسودة السابقة ولا في طلب الموظف.

اكتب نسخة جديدة معدّلة بناءً على طلب التعديل، مع الحفاظ على باقي التفاصيل الصحيحة من المسودة السابقة.`;
}

const imageChangeKeywords = ["صورة", "الصورة", "صور تاني", "image", "غير الصوره", "غيّر الصورة"];
const needsNewImage = mode === "new" ? true : imageChangeKeywords.some(k => text.toLowerCase().includes(k.toLowerCase()));

return {
  json: {
    chatId,
    mode,
    combinedInput,
    needsNewImage
  }
};

let raw = $json.output || "";
raw = raw.replace(/```json/g, "").replace(/```/g, "").trim();

let obj;
try {
  obj = JSON.parse(raw);
} catch (e) {
  obj = { title: "خطأ في التحليل", summary_ar: raw.slice(0, 200), impact_ar: "", category: "Logistics", link: "" };
}

// حماية من الروابط الوهمية
const fakeLinkPatterns = ["example.com", "example.org", "placeholder", "test.com", "yoursite.com", "yourwebsite.com", "domain.com", "sample.com"];
if (obj.link && fakeLinkPatterns.some(p => obj.link.toLowerCase().includes(p))) {
  obj.link = "";
}

// ✅ لو الموديل نسي يطلع اللينك رغم إن الموظف بعته فعليًا، ندوّر عليه بنفسنا في النص الأصلي
if (!obj.link) {
  const originalText = $('Prepare Draft Input1').item.json.combinedInput || "";
  const urlMatch = originalText.match(/(https?:\/\/[^\s"'<>]+)/i);
  if (urlMatch) {
    obj.link = urlMatch[1].replace(/[.,)\]]+$/, ""); // شيل أي علامة ترقيم زايدة في الآخر
  }
}

return {
  json: {
    chatId: $('Prepare Draft Input1').item.json.chatId,
    mode: $('Prepare Draft Input1').item.json.mode,
    needsNewImage: $('Prepare Draft Input1').item.json.needsNewImage,
    draftObj: obj
  }
};

const staticData = $getWorkflowStaticData('global');
if (!staticData.publishedItems) staticData.publishedItems = [];

const obj = $json.draftObj;
const link = (obj.link || "").trim();
const title = (obj.title || "");

function getKeywordSet(t) {
  return new Set(
    (t || "").toLowerCase().replace(/[^\u0600-\u06FFa-z0-9\s]/g, "").split(/\s+/).filter(w => w.length > 2)
  );
}
function similarity(setA, setB) {
  const inter = [...setA].filter(w => setB.has(w)).length;
  const uni = new Set([...setA, ...setB]).size;
  return uni === 0 ? 0 : inter / uni;
}

const set = getKeywordSet(title);

const isDuplicate = staticData.publishedItems.some(p => {
  if (link && p.link && p.link === link) return true;
  const prevSet = new Set(p.titleWords || []);
  return similarity(set, prevSet) > 0.45;
});

return {
  json: {
    ...$json,
    isDuplicate
  }
};

const mainSubject = ($json.draftObj.main_subject || "").trim();
const secondarySubject = ($json.draftObj.secondary_subject || "").trim();
const background = ($json.draftObj.background || "").trim();

const fallbackSubject = "a busy commercial seaport with container ships and cranes";

let prompt;

if (mainSubject.length > 5) {
  prompt =
    `Create a realistic editorial news photo. ` +
    `Primary subject (must occupy most of the frame and be the dominant element): ${mainSubject}. `;

  if (secondarySubject.length > 3) {
    prompt += `Secondary supporting subject (smaller, in the background or to the side - must NOT be larger or more prominent than the primary subject): ${secondarySubject}. `;
  }

  if (background.length > 3) {
    prompt += `Setting/background: ${background}. `;
  }

  prompt +=
    `Modern news editorial photography style, corporate blue color theme, high resolution, realistic photography. ` +
    `Leave clear empty negative space in the upper third of the image for a headline overlay. ` +
    `Square 1:1 aspect ratio. ` +
    `ABSOLUTELY CRITICAL: this image must contain ZERO text, letters, numbers, signs, labels, banners, or writing of any kind, in any language, anywhere in the frame - not on signage, screens, clothing, vehicles, or backgrounds. If the scene would naturally include a sign or label, render it as a blank, unmarked surface instead. ` +
    `No logos, no watermarks, no recognizable real people, not a painting, not an illustration, not a 3D render.`;
} else {
  // بديل احتياطي لو الذكاء الاصطناعي مكتبش موضوع أساسي لأي سبب
  prompt =
    `Modern news editorial photography style, corporate blue color theme, high resolution, realistic photography, ${fallbackSubject}. ` +
    `Leave clear empty negative space in the upper third of the image for a headline overlay. ` +
    `Square 1:1 aspect ratio. No text of any kind inside the image, no logos, no watermarks, no recognizable real people, not a painting, not an illustration, not a 3D render.`;
}

return {
  json: {
    ...$json,
    imagePrompt: prompt
  }
};

for (const item of items) {
  item.binary = item.binary || {};
  item.binary.logo = {
    data: "",
    mimeType: "image/png",
    fileName: "logo.png",
    fileExtension: "png"
  };
}
return items;

const d = $json.draftObj || $('Parse Draft1').item.json.draftObj;
const title = d.title || "";
const summary = d.summary_ar || "";
const impact = d.impact_ar || "";
const link = d.link || "";

let text = `📰 ${title}\n\n📌 ${summary}\n\n⚡ ${impact}`;
if (link) text += `\n\n🔗 ${link}`;

return {
  json: {
    chatId: $('Parse Draft1').item.json.chatId,
    previewText: text,
    draftObj: d
  },
  binary: $input.item.binary
};

const d = $json.draftObj;
const oldFileId = $('Route Message1').item.json.draft ? $('Route Message1').item.json.draft.fileId : null;

const title = d.title || "";
const summary = d.summary_ar || "";
const impact = d.impact_ar || "";
const link = d.link || "";

let text = `📰 ${title}\n\n📌 ${summary}\n\n⚡ ${impact}`;
if (link) text += `\n\n🔗 ${link}`;

return {
  json: {
    chatId: $json.chatId,
    previewText: text,
    draftObj: d,
    fileId: oldFileId
  }
};

const staticData = $getWorkflowStaticData('global');
if (!staticData.chatDrafts) staticData.chatDrafts = {};

const chatId = $('Reuse Existing Image1').item.json.chatId;
const draftObj = $('Reuse Existing Image1').item.json.draftObj;
const previewText = $('Reuse Existing Image1').item.json.previewText;
const fileId = $('Reuse Existing Image1').item.json.fileId;
const oldImagePrompt = staticData.chatDrafts[chatId] ? staticData.chatDrafts[chatId].imagePrompt : "";

staticData.chatDrafts[chatId] = {
  status: "awaiting_confirmation",
  fileId,
  imagePrompt: oldImagePrompt,
  previewText,
  lastDraft: draftObj,
  updatedAt: Date.now()
};

return { json: { ok: true, chatId, fileId } };

const d = $json.draftObj || {};
const title = d.title || "";
const summary = d.summary_ar || "";
const impact = d.impact_ar || "";
const link = d.link || "";

let text = `📰 ${title} (بدون صورة - فشل التوليد)\n\n📌 ${summary}\n\n⚡ ${impact}`;
if (link) text += `\n\n🔗 ${link}`;

return {
  json: {
    chatId: $('Parse Draft1').item.json.chatId,
    previewText: text,
    draftObj: d
  }
};

const staticData = $getWorkflowStaticData('global');
if (!staticData.chatDrafts) staticData.chatDrafts = {};

const chatId = $('Build Text-Only Preview1').item.json.chatId;
const draftObj = $('Build Text-Only Preview1').item.json.draftObj;
const previewText = $('Build Text-Only Preview1').item.json.previewText;

staticData.chatDrafts[chatId] = {
  status: "awaiting_confirmation",
  fileId: null,
  previewText,
  lastDraft: draftObj,
  updatedAt: Date.now()
};

return { json: { ok: true, chatId } };

const chatId = $json.chatId;
const draft = $json.draft;

return {
  json: {
    fromChatId: chatId,
    fileId: draft && draft.fileId ? draft.fileId : null,
    caption: draft && draft.previewText ? draft.previewText : "",
    link: draft && draft.lastDraft ? (draft.lastDraft.link || "") : "",
    title: draft && draft.lastDraft ? (draft.lastDraft.title || "") : ""
  }
};

const staticData = $getWorkflowStaticData('global');
if (!staticData.publishedItems) staticData.publishedItems = [];

const link = $('Prepare Publish1').item.json.link;
const title = $('Prepare Publish1').item.json.title;

function getKeywordSet(t) {
  return [...new Set((t || "").toLowerCase().replace(/[^\u0600-\u06FFa-z0-9\s]/g, "").split(/\s+/).filter(w => w.length > 2))];
}

staticData.publishedItems.push({
  link: (link || "").trim(),
  titleWords: getKeywordSet(title),
  ts: Date.now()
});

// نحافظ على آخر 500 خبر بس عشان الذاكرة متكبرش لانهائيًا
if (staticData.publishedItems.length > 500) {
  staticData.publishedItems = staticData.publishedItems.slice(-500);
}

return { json: { ok: true } };

const staticData = $getWorkflowStaticData('global');
if (!staticData.chatDrafts) staticData.chatDrafts = {};
const chatId = $('Prepare Publish1').item.json.fromChatId;
delete staticData.chatDrafts[chatId];
return { json: { ok: true } };

const staticData = $getWorkflowStaticData('global');

if (!staticData.chatDrafts) {
  staticData.chatDrafts = {};
}

// البيانات الأساسية
const chatId = $('Build Preview Caption1').item.json.chatId;
const draftObj = $('Build Preview Caption1').item.json.draftObj;
const previewText = $('Build Preview Caption1').item.json.previewText;
const imagePrompt = $('Build Image Prompt Chat1').item.json.imagePrompt;

// استجابة Telegram
const telegramResponse = $json;

// استخراج file_id مهما كان شكل الريسبونس
let fileId = null;

if (telegramResponse?.result?.photo?.length) {
  fileId =
    telegramResponse.result.photo[
      telegramResponse.result.photo.length - 1
    ].file_id;
}

else if (telegramResponse?.photo?.length) {
  fileId =
    telegramResponse.photo[
      telegramResponse.photo.length - 1
    ].file_id;
}

else if (telegramResponse?.result?.document?.file_id) {
  fileId = telegramResponse.result.document.file_id;
}

else if (telegramResponse?.document?.file_id) {
  fileId = telegramResponse.document.file_id;
}

// لو معرفش يجيب file_id
if (!fileId) {
  throw new Error(
    "Telegram file_id not found.\n\nTelegram Response:\n" +
    JSON.stringify(telegramResponse, null, 2)
  );
}

// حفظ الـ Draft
staticData.chatDrafts[chatId] = {
  status: "awaiting_confirmation",
  fileId: fileId,
  imagePrompt,
  previewText,
  lastDraft: draftObj,
  updatedAt: Date.now()
};

return {
  json: {
    ok: true,
    chatId,
    fileId,
    telegramResponse
  }
};
